import{_ as o,C as n,o as i,c as s,j as t,a as d,E as r,a2 as l}from"./chunks/framework.Dhr6uKJt.js";const v=JSON.parse('{"title":"Everything ktor-svelte does","description":"","frontmatter":{},"headers":[],"relativePath":"features/index.md","filePath":"features/index.md","lastUpdated":1794931658000}'),h={name:"features/index.md"},c={tabindex:"0"};function u(p,e,g,f,m,y){const a=n("Badge");return i(),s("div",null,[e[5]||(e[5]=t("h1",{id:"everything-ktor-svelte-does",tabindex:"-1"},[d("Everything ktor-svelte does "),t("a",{class:"header-anchor",href:"#everything-ktor-svelte-does","aria-label":'Permalink to "Everything ktor-svelte does"'},"​")],-1)),e[6]||(e[6]=t("p",null,"Every feature in one place, grouped by what you are doing. Each row links to the page that explains it, with snippets and every option.",-1)),e[7]||(e[7]=t("p",null,[t("strong",null,"Where it lives"),d(" tells you where you turn a feature on or use it:")],-1)),t("table",c,[e[4]||(e[4]=t("thead",null,[t("tr",null,[t("th",null,"Label"),t("th",null,"Means")])],-1)),t("tbody",null,[t("tr",null,[t("td",null,[r(a,{type:"tip",text:"Ktor plugin"})]),e[0]||(e[0]=t("td",null,[t("code",null,"install(Svelte) { }"),d(" and helpers in your Kotlin routes, from "),t("code",null,"ktor-svelte-server")],-1))]),t("tr",null,[t("td",null,[r(a,{type:"info",text:"Gradle"})]),e[1]||(e[1]=t("td",null,[t("code",null,"svelte { }"),d(" in "),t("code",null,"build.gradle.kts"),d(", or a Gradle task")],-1))]),t("tr",null,[t("td",null,[r(a,{type:"warning",text:"Generated client"})]),e[2]||(e[2]=t("td",null,[d("Code that ktor-svelte writes into your frontend, imported as "),t("code",null,"#api"),d(", "),t("code",null,"#routes"),d(" or "),t("code",null,"#components/...")],-1))]),t("tr",null,[t("td",null,[r(a,{type:"danger",text:"Test kit"})]),e[3]||(e[3]=t("td",null,[t("code",null,"ktor-svelte-test"),d(", for Kotlin tests that drive a browser")],-1))])])]),e[8]||(e[8]=l('<p>A few rows say Recipe, Script, Docs, Release or This site instead: those are guides, the setup script, or things that happen outside your app.</p><p>New here? Start with <a href="./../guide/getting-started">Getting started</a> or the <a href="./../guide/tutorial">tutorial</a>. Looking for a whole solution, such as sign in or uploads? See the <a href="./../recipes/">recipes</a>.</p><nav class="table-of-contents"><ul><li><a href="#kotlin-to-typescript">Kotlin to TypeScript</a><ul><li><a href="#the-generated-client">The generated client</a></li><li><a href="#calling-the-api">Calling the API</a></li><li><a href="#validation-and-forms">Validation and forms</a></li><li><a href="#config-and-transport">Config and transport</a></li></ul></li><li><a href="#frontend">Frontend</a><ul><li><a href="#pages-and-links">Pages and links</a></li><li><a href="#look-and-feel">Look and feel</a></li><li><a href="#languages">Languages</a></li><li><a href="#components">Components</a></li></ul></li><li><a href="#users-and-security">Users and security</a></li><li><a href="#develop">Develop</a></li><li><a href="#test">Test</a></li><li><a href="#ship-and-run">Ship and run</a></li><li><a href="#still-missing-something">Still missing something?</a></li></ul></nav><h2 id="kotlin-to-typescript" tabindex="-1">Kotlin to TypeScript <a class="header-anchor" href="#kotlin-to-typescript" aria-label="Permalink to &quot;Kotlin to TypeScript&quot;">​</a></h2><p>Your Ktor routes and classes become a typed client, so the frontend breaks at compile time, not in production.</p><h3 id="the-generated-client" tabindex="-1">The generated client <a class="header-anchor" href="#the-generated-client" aria-label="Permalink to &quot;The generated client&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Where it lives</th></tr></thead><tbody><tr><td><a href="./typescript">Generated TypeScript</a></td><td>Types, services, <code>validate()</code>, <code>empty()</code> and enum objects for every route, written to <code>frontend/src/lib/api</code> with no npm dependencies</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./typescript#getting-exact-types">Exact types</a></td><td>Ktor&#39;s compiler plugin reads <code>receive</code> and <code>respond</code>, or you describe a route by hand</td><td>Gradle</td></tr><tr><td><a href="./typescript#documentation-in-the-editor">Documentation in the editor</a></td><td><code>describe { }</code> and <code>@JsonSchema.Description</code> become JSDoc, deprecations become <code>@deprecated</code>, and each function names its Kotlin file</td><td>Generated client</td></tr><tr><td><a href="./typescript">Dates</a></td><td><code>LocalDate</code>, <code>LocalTime</code>, <code>Instant</code> and <code>LocalDateTime</code> become <code>IsoDate</code>, <code>IsoTime</code> and <code>IsoDateTime</code>, with safe converters</td><td>Generated client</td></tr><tr><td><a href="./typescript#shared-constants">Shared constants</a></td><td>A Kotlin object with limits and lists, written to <code>constants.ts</code></td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./typescript#ids-that-cannot-be-mixed-up">IDs that cannot be mixed up</a></td><td>A Kotlin value class becomes its own TypeScript type</td><td>Generated client</td></tr><tr><td><a href="./typescript#money-and-durations">Money and durations</a></td><td>Exact <code>Decimal</code> values and <code>Duration</code> as text, with helpers</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./typescript#sealed-classes">Sealed classes</a></td><td>A union with a <code>type</code> field and an exhaustive <code>match</code></td><td>Generated client</td></tr><tr><td><a href="./typescript#resource-routes">Resource routes</a></td><td><code>resource</code> registers list, get, create, update and delete with the names the client expects</td><td>Ktor plugin</td></tr><tr><td><a href="./typescript#routes-nothing-calls">Routes nothing calls</a></td><td><code>svelteVerifyApiRoutes</code> lists API routes the frontend never uses</td><td>Gradle</td></tr><tr><td><a href="./typescript#what-changed-for-callers">What changed for callers</a></td><td><code>svelteApiChanges</code> compares the API with another git revision</td><td>Gradle</td></tr><tr><td><a href="./playground">Generator playground</a></td><td>Paste an OpenAPI document and see the TypeScript it becomes, in the browser</td><td>This site</td></tr></tbody></table><h3 id="calling-the-api" tabindex="-1">Calling the API <a class="header-anchor" href="#calling-the-api" aria-label="Permalink to &quot;Calling the API&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Where it lives</th></tr></thead><tbody><tr><td><a href="./calling-the-api">Typed calls and errors</a></td><td><code>api.notes.list()</code>, <code>isApiError</code>, <code>isValidationError</code>, <code>errorMessage</code>, event streams and uploads</td><td>Generated client</td></tr><tr><td><a href="./calling-the-api#prefetch-on-hover">Prefetch on hover</a></td><td>Load a page&#39;s data, or one call, while the pointer rests on a link</td><td>Generated client</td></tr><tr><td><a href="./calling-the-api#error-codes">Error codes</a></td><td>Named errors from one Kotlin enum instead of status numbers</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./calling-the-api#query-parameters-as-a-class">Query parameters as a class</a></td><td><code>call.query&lt;T&gt;()</code> reads the query string into a class, and the client gets its type</td><td>Ktor plugin</td></tr><tr><td><a href="./calling-the-api#changing-some-fields">Changing some fields</a></td><td><code>Patch&lt;T&gt;</code> for <code>PATCH</code> routes that tell &quot;not sent&quot; from &quot;set to null&quot;</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./calling-the-api#two-people-one-record">Two people, one record</a></td><td>A version check that refuses a save over someone else&#39;s change</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./../reference/ktor#path-parameters">Path parameters</a></td><td><code>call.pathParameter&lt;T&gt;(name)</code> reads a path parameter as a number, UUID or enum</td><td>Ktor plugin</td></tr><tr><td><a href="./../recipes/pagination">Paged lists</a></td><td><code>Page&lt;T&gt;</code> and <code>getPage</code> on the server, <code>pages()</code> in the browser</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./calling-the-api#only-some-fields">Only some fields</a></td><td><code>?fields=id,title</code> sends only those fields, and the client&#39;s return type narrows to them</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./calling-the-api#included-relations">Included relations</a></td><td><code>?include=author</code> adds related objects, typed so the field exists only when asked for</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./../recipes/uploads">Uploads</a></td><td><code>FormData</code> bodies with upload progress, and size and type rules shared by both sides</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./../recipes/live-updates">Live updates</a></td><td>Server-sent events become async generators in the client</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./calling-the-api#in-load-functions">In load functions</a></td><td><code>apiWith(event)</code> runs every call through SvelteKit&#39;s <code>fetch</code></td><td>Generated client</td></tr><tr><td><a href="./calling-the-api#refresh-the-page-after-a-write">Refresh the page after a write</a></td><td><code>onWrite</code> reruns the page&#39;s <code>load</code> functions after a successful write</td><td>Generated client</td></tr><tr><td><a href="./calling-the-api#ask-before-a-call">Ask before a call</a></td><td><code>confirmed</code> asks first and only calls on yes</td><td>Generated client</td></tr><tr><td><a href="./calling-the-api#show-errors-automatically">Show errors automatically</a></td><td>Every failed call shows a toast, with no error handling in components</td><td>Gradle, Generated client</td></tr><tr><td><a href="./calling-the-api#toasts-from-the-server">Toasts from the server</a></td><td><code>call.toast(...)</code> in a route shows a message in the browser</td><td>Ktor plugin</td></tr><tr><td><a href="./calling-the-api#navigation-from-the-server">Navigation from the server</a></td><td><code>call.navigateTo(...)</code> tells the browser which page to open next</td><td>Ktor plugin</td></tr><tr><td><a href="./calling-the-api#reload-after-a-deploy">Reload after a deploy</a></td><td>The client notices a new build and can offer a reload</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./calling-the-api#request-ids">Request IDs</a></td><td>Every call carries an <code>X-Request-Id</code> that reaches your logs and the error</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./calling-the-api#timeouts">Timeouts</a></td><td>One timeout for every call, or one per call</td><td>Generated client</td></tr><tr><td><a href="./calling-the-api#retries">Retries</a></td><td>GET requests that failed on the network are tried again</td><td>Generated client</td></tr><tr><td><a href="./calling-the-api#rate-limits">Rate limits</a></td><td><code>isRateLimitError</code> and <code>retryAfter</code>, and with retries on, one automatic wait and retry</td><td>Generated client</td></tr><tr><td><a href="./calling-the-api#writes-that-are-safe-to-send-twice">Writes that are safe to send twice</a></td><td>Idempotency keys, so a repeated write is answered once</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./calling-the-api#the-visitor-s-time-zone">The visitor&#39;s time zone</a></td><td><code>call.timeZone</code> in every route, sent by the client</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./calling-the-api#search-as-you-type">Search as you type</a></td><td><code>latest</code> aborts the previous call, so an old answer never wins</td><td>Generated client</td></tr><tr><td><a href="./calling-the-api#fixtures-for-frontend-tests">Fixtures for frontend tests</a></td><td>Record real answers in the dev panel and replay them without a backend</td><td>Generated client</td></tr></tbody></table><h3 id="validation-and-forms" tabindex="-1">Validation and forms <a class="header-anchor" href="#validation-and-forms" aria-label="Permalink to &quot;Validation and forms&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Where it lives</th></tr></thead><tbody><tr><td><a href="./validation">Validation</a></td><td><code>@JsonSchema</code> bounds and <code>Validated</code> rules, checked on every <code>receive</code>, with field errors in a 422 and the same bounds in the browser</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./validation#cleaning-up-input">Cleaning up input</a></td><td><code>@Trim</code>, <code>@Lowercase</code> and <code>@EmptyAsNull</code>, declared on the field</td><td>Ktor plugin</td></tr><tr><td><a href="./validation#sensitive-fields">Sensitive fields</a></td><td>Mark a password or token once, and the dev tools show <code>***</code></td><td>Ktor plugin</td></tr><tr><td><a href="./validation#form-state">Form state</a></td><td><code>formState</code> holds the values, changes, submit state and errors of a form</td><td>Generated client</td></tr><tr><td><a href="./validation#checks-only-the-server-can-make">Checks only the server can make</a></td><td>&quot;Is this email taken?&quot; while the visitor types</td><td>Ktor plugin, Generated client</td></tr></tbody></table><h3 id="config-and-transport" tabindex="-1">Config and transport <a class="header-anchor" href="#config-and-transport" aria-label="Permalink to &quot;Config and transport&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Where it lives</th></tr></thead><tbody><tr><td><a href="./runtime-config">Runtime config</a></td><td><code>publicConfig</code> passes values to the frontend at startup, inlined into every page</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./runtime-config#changing-values-without-a-restart">Changing values without a restart</a></td><td>Pass a function, and development picks up edits on the next page load</td><td>Ktor plugin</td></tr><tr><td><a href="./runtime-config#environment-variables">Environment variables</a></td><td><code>environment</code> declares every variable in one place, with types and a <code>.env.example</code></td><td>Ktor plugin, Gradle</td></tr><tr><td><a href="./runtime-config#secrets-in-the-frontend-build">Secrets in the frontend build</a></td><td><code>svelteVerifyLeaks</code> fails the build when a secret reached the built files</td><td>Gradle</td></tr><tr><td><a href="./transport">Transport</a></td><td><code>json()</code>, <code>xml()</code>, other formats and <code>compression()</code> in one block</td><td>Ktor plugin</td></tr><tr><td><a href="./transport#api-compression">API compression</a></td><td>API responses compressed by default, with zstd when you add it</td><td>Ktor plugin</td></tr></tbody></table><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><p>Pages, links, styling and components, turned on in Gradle and typed on both sides. <a href="./frontend-libraries">Frontend libraries</a> is the overview of every library.</p><h3 id="pages-and-links" tabindex="-1">Pages and links <a class="header-anchor" href="#pages-and-links" aria-label="Permalink to &quot;Pages and links&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Where it lives</th></tr></thead><tbody><tr><td><a href="./routes">Typed routes</a></td><td>Every page as a typed constant: <code>routes</code> in Svelte, <code>FrontendRoutes</code> in Kotlin</td><td>Gradle, Generated client</td></tr><tr><td><a href="./routes#marking-the-open-page-in-a-menu">Marking the open page</a></td><td><code>isActive</code> for menus, without comparing paths</td><td>Generated client</td></tr><tr><td><a href="./routes#menu-titles-and-breadcrumbs">Menu, titles and breadcrumbs</a></td><td>Each page says its own title and icon in <code>+page.ts</code></td><td>Gradle, Generated client</td></tr><tr><td><a href="./routes#link-previews">Link previews</a></td><td>Tags for chat and social previews, from the same page metadata</td><td>Gradle, Generated client</td></tr><tr><td><a href="./routes#a-new-page">A new page</a></td><td><code>svelteAdd --page</code> writes a page with a typed load</td><td>Gradle</td></tr><tr><td><a href="./routes#pages-for-a-class">Pages for a class</a></td><td><code>svelteAdd --crud</code> writes list, detail and form pages from the generated client</td><td>Gradle</td></tr><tr><td><a href="./routes#renaming-a-page">Renaming a page</a></td><td><code>svelteRename</code> moves a page and fixes every typed call to it</td><td>Gradle</td></tr><tr><td><a href="./routes#finding-links-that-are-still-strings">Links that are still strings</a></td><td><code>svelteVerifyRoutes</code> finds string links and suggests the typed call</td><td>Gradle</td></tr><tr><td><a href="./routes#finding-links-that-lead-nowhere">Links that lead nowhere</a></td><td><code>svelteVerifyLinks</code> finds links to pages that do not exist</td><td>Gradle</td></tr></tbody></table><h3 id="look-and-feel" tabindex="-1">Look and feel <a class="header-anchor" href="#look-and-feel" aria-label="Permalink to &quot;Look and feel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Where it lives</th></tr></thead><tbody><tr><td><a href="./styling#tailwind">Tailwind</a></td><td>Tailwind 4 in Vite and the CSS, with the typography and forms plugins</td><td>Gradle</td></tr><tr><td><a href="./styling#daisyui">DaisyUI themes</a></td><td>Components and themes, typed in TypeScript and Kotlin, with no flash of the wrong theme</td><td>Gradle, Generated client</td></tr><tr><td><a href="./styling#shadcn-themes">shadcn themes</a></td><td>The shadcn/ui look for every DaisyUI component</td><td>Gradle</td></tr><tr><td><a href="./styling#custom-themes">Custom themes</a></td><td>Your own colors, and a dev panel editor to tune them live</td><td>Gradle</td></tr><tr><td><a href="./styling#fonts">Fonts</a></td><td>A font served from your own app, preloaded</td><td>Gradle</td></tr><tr><td><a href="./icons-and-images#lucide-icons">Lucide icons</a></td><td>A typed <code>LucideIcon</code> enum and an <code>&lt;Icon&gt;</code> component, with only the icons you use</td><td>Gradle, Generated client</td></tr><tr><td><a href="./icons-and-images#images">Images</a></td><td><code>&lt;enhanced:img&gt;</code> with AVIF and WebP in several widths</td><td>Gradle</td></tr><tr><td><a href="./charts">Charts</a></td><td>LayerChart in your theme colors, with typed series</td><td>Gradle, Generated client</td></tr><tr><td><a href="./installable-app">Installable app</a></td><td>A web manifest, icons, a service worker and an offline page</td><td>Gradle, Ktor plugin</td></tr><tr><td><a href="./emails">Emails</a></td><td>Svelte components rendered to HTML and text emails at build time, with a typed Kotlin function per email</td><td>Gradle</td></tr></tbody></table><h3 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Where it lives</th></tr></thead><tbody><tr><td><a href="./i18n">i18n</a></td><td>Typed messages from one JSON file per language, in Svelte and in Kotlin</td><td>Gradle, Generated client</td></tr><tr><td><a href="./i18n#strategies">Strategies</a></td><td>The language from a cookie or from a URL prefix</td><td>Gradle</td></tr><tr><td><a href="./i18n#plurals">Plurals</a></td><td>&quot;1 note&quot; and &quot;2 notes&quot; as one message</td><td>Gradle, Generated client</td></tr><tr><td><a href="./i18n#numbers-money-and-dates">Numbers, money and dates</a></td><td>Formats that read the same in the browser and on the server</td><td>Gradle, Generated client</td></tr><tr><td><a href="./i18n#relative-time">Relative time</a></td><td>&quot;3 minutes ago&quot;, in the visitor&#39;s language</td><td>Generated client</td></tr><tr><td><a href="./i18n#messages-nobody-translated-yet">Messages nobody translated yet</a></td><td>The dev panel marks copied, untranslated texts</td><td>Gradle</td></tr><tr><td><a href="./i18n#messages-nothing-uses">Messages nothing uses</a></td><td><code>svelteVerifyMessages</code> lists keys you can delete</td><td>Gradle</td></tr></tbody></table><h3 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Where it lives</th></tr></thead><tbody><tr><td><a href="./components">Components</a></td><td>Svelte components over the generated helpers, imported as <code>#components/...</code></td><td>Gradle, Generated client</td></tr><tr><td><a href="./components#field">Field</a></td><td>Label, input, hint and validation errors in one</td><td>Generated client</td></tr><tr><td><a href="./components#dateinput-and-datetimeinput">DateInput and DateTimeInput</a></td><td>Inputs that bind to <code>IsoDate</code> and <code>IsoDateTime</code></td><td>Generated client</td></tr><tr><td><a href="./components#enumselect">EnumSelect</a></td><td>A <code>&lt;select&gt;</code> over a generated enum</td><td>Generated client</td></tr><tr><td><a href="./components#datatable">DataTable</a></td><td>A table over any paged route, with loading, empty and error states</td><td>Generated client</td></tr><tr><td><a href="./components#filedrop">FileDrop</a></td><td>A drop area with previews, progress and refusal reasons</td><td>Generated client</td></tr><tr><td><a href="./components#errorpage">ErrorPage</a></td><td>The page SvelteKit shows when a page cannot load</td><td>Generated client</td></tr><tr><td><a href="./components#themetoggle-and-localeswitch">ThemeToggle and LocaleSwitch</a></td><td>Theme and language switches that know your configuration</td><td>Generated client</td></tr><tr><td><a href="./components#timeago">TimeAgo</a></td><td>A relative time that keeps itself current</td><td>Generated client</td></tr><tr><td><a href="./components#navigationprogress">NavigationProgress</a></td><td>A thin bar while SvelteKit navigates</td><td>Generated client</td></tr><tr><td><a href="./components#modals">Modals</a></td><td><code>modal()</code> opens a <code>&lt;dialog&gt;</code> and tells you how it closed</td><td>Generated client</td></tr><tr><td><a href="./components#toasts">Toasts</a></td><td>A <code>toast()</code> helper and an optional reload prompt</td><td>Gradle, Generated client</td></tr></tbody></table><h2 id="users-and-security" tabindex="-1">Users and security <a class="header-anchor" href="#users-and-security" aria-label="Permalink to &quot;Users and security&quot;">​</a></h2><p>Sign in, permissions and the protections that are on by default.</p><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Where it lives</th></tr></thead><tbody><tr><td><a href="./auth">Auth</a></td><td>Put the frontend behind Ktor&#39;s authentication, with public paths you list</td><td>Ktor plugin</td></tr><tr><td><a href="./auth#the-current-user">The current user</a></td><td>Declare once how the server finds the user, and get a typed <code>currentUser</code> store</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./auth#in-routes">The user in routes</a></td><td><code>call.user</code> in every route, typed</td><td>Ktor plugin</td></tr><tr><td><a href="./auth#when-the-session-ends">When the session ends</a></td><td>A warning before the session ends, with an optional way to extend it</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./auth#permissions">Permissions</a></td><td>One enum and one function, checked on the server and shown in the browser</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./auth#page-guards">Page guards</a></td><td>Which pages need a user or a permission, declared once by page</td><td>Ktor plugin</td></tr><tr><td><a href="./auth#user-preferences">User preferences</a></td><td>Theme, language and other choices that follow a person to every device</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./auth#the-login-page">The login page</a></td><td>Every &quot;please sign in&quot; ends at your login page, and returns where it started</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./../recipes/sessions">Sessions</a></td><td>Sign in with a session cookie, as a recipe</td><td>Recipe</td></tr><tr><td><a href="./../recipes/sessions#typed-cookies">Typed cookies</a></td><td>Cookies as typed values on both sides</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./../recipes/sessions#cookie-consent">Cookie consent</a></td><td>A consent helper for cookies that need one</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./../recipes/admin-area">Admin area</a></td><td>Pages and routes only admins may use, as a recipe</td><td>Recipe</td></tr><tr><td><a href="./../security#security-headers">Security headers</a></td><td><code>nosniff</code>, frame and referrer headers, and a strict Content-Security-Policy from build hashes</td><td>Ktor plugin</td></tr><tr><td><a href="./../security#api-request-guards">API request guards</a></td><td>Origin check, body size limit, JSON depth, rate limit and hidden error details</td><td>Ktor plugin</td></tr><tr><td><a href="./../security#malformed-requests">Malformed requests</a></td><td>Broken paths and hosts answer 400, without noise in your log</td><td>Ktor plugin</td></tr><tr><td><a href="./endpoints#who-may-see-internal-endpoints">Who may see internal endpoints</a></td><td>Open the status endpoint and API docs to the callers you name</td><td>Ktor plugin</td></tr><tr><td><a href="./../security#verifying-a-release">Verifying a release</a></td><td>Signed build provenance and an SBOM for every release</td><td>Release</td></tr></tbody></table><h2 id="develop" tabindex="-1">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to &quot;Develop&quot;">​</a></h2><p>The dev loop, the dev panel and the tools around them.</p><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Where it lives</th></tr></thead><tbody><tr><td><a href="./../guide/getting-started">Setup script</a></td><td>One command creates a project with everything wired up</td><td>Script</td></tr><tr><td><a href="./../guide/configurator">Configurator</a></td><td>Tick options and copy the settings</td><td>This site</td></tr><tr><td><a href="./../guide/dev-workflow">Dev workflow</a></td><td><code>svelteDevAll</code> runs Vite, the compiler and your app with hot reload on one port, in one readable log</td><td>Gradle</td></tr><tr><td><a href="./../guide/dev-workflow">Dev panel</a></td><td>Every API call with replay, curl, payload size, SQL counts and duplicates, plus status, slowest routes, environment, migrations, memory and threads, caught emails, cookies, clear site data, routes, public config, accessibility and a theme editor</td><td>Ktor plugin</td></tr><tr><td><a href="./../guide/dev-workflow">Server error overlay</a></td><td>A failed call shows the exception and a link to your code in the browser</td><td>Ktor plugin</td></tr><tr><td><a href="./../guide/dev-workflow">Browser logs in your console</a></td><td><code>console.log</code> and browser errors land in the dev log</td><td>Ktor plugin</td></tr><tr><td><a href="./../guide/dev-workflow">Restart summary and startup timing</a></td><td>What caused a restart, how long it took, and where startup time went</td><td>Gradle, Ktor plugin</td></tr><tr><td><a href="./../guide/multiple-frontends">Multiple frontends</a></td><td>A public site and an admin area as two SvelteKit projects under their own path prefixes, in one app and one JAR</td><td>Ktor plugin, Gradle</td></tr><tr><td><a href="./../guide/dev-workflow#https-in-development">HTTPS in development</a></td><td>Develop with <code>Secure</code> cookies and service workers</td><td>Gradle</td></tr><tr><td><a href="./../guide/dev-workflow#when-a-port-is-still-in-use">When a port is still in use</a></td><td>Leftover processes from a crash are cleaned up</td><td>Gradle</td></tr><tr><td><a href="./../guide/dev-workflow">Debugging</a></td><td>Run configurations to debug Kotlin and the frontend, in one click</td><td>Gradle</td></tr><tr><td><a href="./../guide/checks-and-tooling#sveltelivetemplates">Live templates</a></td><td><code>ksget</code>, <code>ksapi</code> and more for IntelliJ and WebStorm</td><td>Gradle</td></tr><tr><td><a href="./../guide/checks-and-tooling">Checks and tooling</a></td><td>Every verify task, what it catches and when it runs</td><td>Gradle</td></tr><tr><td><a href="./../guide/checks-and-tooling#svelteverifynaming">Naming rules</a></td><td><code>svelteVerifyNaming</code> checks pages, API routes, DTOs and message keys against the rules you set</td><td>Gradle</td></tr><tr><td><a href="./../guide/checks-and-tooling#sveltedoctor">svelteDoctor</a></td><td>Checks the setup and fixes what it can with <code>--fix</code></td><td>Gradle</td></tr><tr><td><a href="./../guide/checks-and-tooling#svelteconfig">svelteConfig</a></td><td>Every setting on both sides, scored with suggestions</td><td>Gradle</td></tr><tr><td><a href="./../guide/checks-and-tooling#format-and-formatcheck">Format both sides</a></td><td><code>format</code> and <code>formatCheck</code> for Kotlin and the frontend</td><td>Gradle</td></tr><tr><td><a href="./../guide/checks-and-tooling#the-git-pre-commit-hook">Git pre-commit hook</a></td><td>Stops unformatted or stale files before a commit, and merges generated files</td><td>Gradle</td></tr><tr><td><a href="./../guide/checks-and-tooling#lint-rules">Lint rules</a></td><td>ESLint rules for mistakes that are easy to make in a ktor-svelte app, shown while you type</td><td>Gradle, Generated client</td></tr><tr><td><a href="./components#guide-for-coding-assistants">Guide for coding assistants</a></td><td>An <code>AGENTS.md</code> that tells assistants how the project works</td><td>Gradle</td></tr><tr><td><a href="./../reference/gradle#short-task-names">Short task names</a></td><td><code>dev</code>, <code>sync</code>, <code>doctor</code> and <code>gen</code></td><td>Gradle</td></tr><tr><td><a href="./../reference/gradle#pin-bun">Pin Bun</a></td><td>Set <code>bunVersion</code>, and the plugin downloads that exact Bun, so a fresh machine builds too</td><td>Gradle</td></tr></tbody></table><h2 id="test" tabindex="-1">Test <a class="header-anchor" href="#test" aria-label="Permalink to &quot;Test&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Where it lives</th></tr></thead><tbody><tr><td><a href="./../guide/browser-tests">Browser tests</a></td><td>Kotlin tests that drive Chromium, Firefox or WebKit against the packaged app</td><td>Test kit, Gradle</td></tr><tr><td><a href="./../guide/browser-tests#record-a-test">Record a test</a></td><td>Click through the app once and get the test written down</td><td>Gradle</td></tr><tr><td><a href="./../guide/browser-tests#the-api-with-your-own-classes">The API with your own classes</a></td><td>Call the API from a test with your Kotlin classes</td><td>Test kit</td></tr><tr><td><a href="./../guide/browser-tests#accessibility">Accessibility</a></td><td><code>svelteVerifyA11y</code> runs axe on every prerendered page, light and dark</td><td>Gradle</td></tr><tr><td><a href="./../guide/deployment#smoke-test">Smoke test</a></td><td><code>svelteSmokeTest</code> starts the packaged app in production mode and checks every page</td><td>Gradle</td></tr><tr><td><a href="./calling-the-api#fixtures-for-frontend-tests">Fixtures for frontend tests</a></td><td>Frontend tests that answer from recorded calls</td><td>Generated client</td></tr></tbody></table><h2 id="ship-and-run" tabindex="-1">Ship and run <a class="header-anchor" href="#ship-and-run" aria-label="Permalink to &quot;Ship and run&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th><th>Where it lives</th></tr></thead><tbody><tr><td><a href="./../guide/deployment#build-the-jar">Build the JAR</a></td><td><code>jar</code>, Shadow or <code>buildFatJar</code>, each with the frontend inside</td><td>Gradle</td></tr><tr><td><a href="./../guide/deployment#docker">Docker</a></td><td>A multi-stage build that runs as a non-root user</td><td>Script</td></tr><tr><td><a href="./../guide/deployment#railway">Railway</a></td><td><code>svelteDeploy</code> writes Railway&#39;s config from what the project knows</td><td>Gradle</td></tr><tr><td><a href="./../guide/deployment#a-plain-server">A plain server</a></td><td>A systemd unit for the JAR</td><td>Docs</td></tr><tr><td><a href="./../guide/deployment#behind-a-reverse-proxy">Behind a reverse proxy</a></td><td>nginx, Caddy or a load balancer in front to terminate TLS</td><td>Docs</td></tr><tr><td><a href="./../reference/how-it-works">Caching and precompressed files</a></td><td>Immutable caching, ETags, zstd, Brotli and gzip, real 404s for stale chunks</td><td>Ktor plugin, Gradle</td></tr><tr><td><a href="./endpoints">Built-in endpoints</a></td><td>Sitemap, <code>robots.txt</code>, a default favicon, status, health and Swagger UI</td><td>Ktor plugin</td></tr><tr><td><a href="./endpoints#health-endpoint">Health endpoint</a></td><td><code>/_ktor-svelte/health</code> for load balancers, with your own checks</td><td>Ktor plugin</td></tr><tr><td><a href="./../guide/monitoring">Monitoring</a></td><td>What to watch in production, in one place</td><td>Ktor plugin</td></tr><tr><td><a href="./../guide/monitoring#request-log">Request log</a></td><td>One line per request in production</td><td>Ktor plugin</td></tr><tr><td><a href="./../guide/monitoring#errors-from-the-browser">Errors from the browser</a></td><td>Frontend errors reach your server log</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./../guide/monitoring#page-timings">Page timings</a></td><td>Web vitals from real browsers, also as metrics</td><td>Ktor plugin, Generated client</td></tr><tr><td><a href="./../guide/monitoring#refused-requests">Refused requests</a></td><td>Counters for every request the guards refused</td><td>Ktor plugin</td></tr><tr><td><a href="./../guide/monitoring#build-info">Build info</a></td><td>Version and commit on both sides, without setup</td><td>Gradle, Ktor plugin</td></tr><tr><td><a href="./../guide/deployment#checklist">Checklist</a></td><td>What to check before the first deploy</td><td>Docs</td></tr></tbody></table><h2 id="still-missing-something" tabindex="-1">Still missing something? <a class="header-anchor" href="#still-missing-something" aria-label="Permalink to &quot;Still missing something?&quot;">​</a></h2><ul><li>Settings by name: <a href="./../reference/gradle">Gradle settings and tasks</a> and <a href="./../reference/ktor">Ktor settings</a></li><li>Something broke: <a href="./../reference/troubleshooting">Troubleshooting</a></li><li>What is planned next: <a href="https://github.com/nijasc/ktor-svelte/blob/main/FEATURES_NEXT.md" target="_blank" rel="noreferrer"><code>FEATURES_NEXT.md</code></a></li></ul>',35))])}const w=o(h,[["render",u]]);export{v as __pageData,w as default};
